import React, {useState} from 'react';
import {Button, Dialog, DialogContent, DialogTitle, Fab, Icon, Typography} from "@mui/material";
import Box from "@mui/material/Box";
import {t} from "i18next";
import OnlineChecker from "../../components/shared/OnlineChecker";
import TextField from "@mui/material/TextField";
import PriceFormat from "../../components/shared/PriceFormat";
import PercentageFormat from "../../components/shared/PercentageFormat";

const NewGoal = () => {

    const [isOpen, setOpen] = useState(false);

    const [nameInput, setNameInput] = useState('')
    const [percentageInput, setPercentageInput] = useState()

    const [max, setMax] = useState(100);
    const [min, setMin] = useState(0);

    return (
        <Box>
            <Fab variant="extended" color="primary" aria-label="add" onClick={()=>setOpen(true)}>
                <Icon>add</Icon>
                {t(`New Saving Goal`)}
            </Fab>

            <Dialog open={isOpen} onClose={()=>setOpen(false)} >
                <DialogTitle id="quick-input-title">
                    <Box display={'flex'} alignItems={'center'} >
                        <Icon onClick={()=>setOpen(false)} style={{cursor: "pointer", marginRight: "8%"}}  >
                            arrow_back
                        </Icon>


                        <Typography variant={'h4'} >
                            {t(`New Saving Goal`)}
                        </Typography>
                    </Box>


                </DialogTitle>

                <Box
                    component="form"
                    sx={{
                        '& .MuiTextField-root': { m: 1, width: '25ch' },
                        'display': 'flex',
                        'flexDirection':'column'
                    }}
                    noValidate

                    onSubmit={e=>{
                        e.preventDefault();
                    }}
                >
                    <DialogContent sx={{
                        '& .MuiTextField-root': { m: 1, width: '25ch' },
                        'display': 'flex',
                        'flexDirection':'column'
                    }}>
                        <OnlineChecker/>

                        <TextField id="name"
                                   type="text"

                                   label={t(`Name`)}
                                   variant="outlined"
                                   value={nameInput}
                                   onChange={(e) => setNameInput(e.target.value)}


                        />

                        <TextField id="percentage"

                                   label={t("Percentage")}
                                   variant="outlined"
                                   value={percentageInput}
                                   error={!percentageInput || percentageInput > max || percentageInput <= min}

                                   onChange={(e) => {
                                       setPercentageInput(e.target.value)
                                   }}
                                   InputProps={{
                                       inputComponent: PercentageFormat,
                                   }}

                        />

                    </DialogContent>
                </Box>

            </Dialog>
        </Box>
    );
};

export default NewGoal;