import React, {useEffect, useState} from 'react';
import {ThemeProvider} from "@mui/material/styles";
import {theme, themeRed} from "../../config/ThemeMUI";
import {Button, CircularProgress, Container, Icon, Stack, Typography} from "@mui/material";
import {calculateAverage, calculateTotal, formatMoney} from "../../util";
import QuickInput from "../../components/income-outcome/quickInput";
import {t} from "i18next";
import {useLocation, useNavigate} from "react-router-dom";
import {linearProgressBoxSx, mainStackSx} from "../../config/SxStyles";
import TextField from "@mui/material/TextField";
import Header from "../shared/Header";
import {fetchSavingData} from "../../services/savingService";
import {fetchIncomeData} from "../../services/incomeService";
import {fetchFrequentData} from "../../services/frequentService";
import PriceFormat from "../../components/shared/PriceFormat";
import LinearProgress from "@mui/material/LinearProgress";
import Box from "@mui/material/Box";
import InputField from "./InputField";
import NewGoal from "./NewGoal";
import SavingsTable from "./SavingsTable";
import {fetchSeveral} from "../../services/mainService";
import {fetchOutcomeData} from "../../services/outcomeService";

const Savings = () => {
    const location = useLocation();
    const auth = location.state?.auth;
    const language = location.state?.language;


    const currentDate = new Date()

    const [income, setIncome] = useState(0);
    const [budget, setBudget] = useState(0);

    const [isLoading, setIsLoading] = useState(true);

    const fetchKnownData = async () => {

        setIsLoading(true)
        const income = await fetchIncomeData(auth, currentDate.getMonth() + 1, currentDate.getFullYear());
        const frequent = await fetchFrequentData(auth);

        const pastExpenses = await fetchSeveral(auth, fetchOutcomeData, currentDate, 2);

        const averageExpenses = (calculateAverage(pastExpenses, 'price'))
        const totalFrequent = calculateTotal(frequent.docs, 'price')

        console.log('Past says: ', formatMoney(averageExpenses), 'Planning says: ', formatMoney(totalFrequent))

        const accurrateBudget = Math.round((averageExpenses * 0.4) + (totalFrequent * 0.6))
        setIncome(calculateTotal(income.docs, 'price'))
        setBudget(accurrateBudget)

        setIsLoading(false)

    }

    useEffect(() => {
        fetchKnownData().then()
    }, []);
    return (
        <ThemeProvider theme={theme}>
            <Stack   sx={mainStackSx}>

                <Header title={'Saving Goals'}/>

                <Box sx={linearProgressBoxSx}>
                    {isLoading ? <LinearProgress/> : <></>}
                </Box>




                <InputField name={'Income'} value={income} setValue={setIncome} help={'The sum of all your income sources for the month.'}/>


                <InputField name={'Budget'} value={budget} setValue={setBudget} help={'Combines your average monthly expenses with your monthly budget to create a realistic budget'}/>


                <Typography variant={'h3'}>{t('Disposable Income')}:</Typography>
                <Typography>{formatMoney(income-budget)}</Typography>
                <NewGoal/>
                <SavingsTable/>




            </Stack>
        </ThemeProvider>
    );
};

export default Savings;